esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: attempt withdraw for this contract (msg.sender == this)
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Do not call deposit to avoid triggering its assert; assume c starts with some balance possibly 0.
        // Capture balances before the call via public observable interfaces.
        uint256 beforeContractBal = address(c).balance;
        // There's no public getter for balances mapping (it's private), so we will observe effect via contract balance
        // and via trying to withdraw and observing revert; we can't read per-address balance, so we use the observable
        // guarantee: withdraw only allows withdrawing up to recorded balance and transfers that amount.

        bool withdrewReverted;
        uint256 beforeThisBal = address(this).balance;
        // Attempt withdraw from c as this contract
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }
        uint256 afterContractBal = address(c).balance;
        uint256 afterThisBal = address(this).balance;

        // General rule:
        // If withdraw reverted, contract and this balances unchanged; otherwise
        // - this contract's balance increased by exactly the lesser of amount and the recorded balance; but we cannot read recorded balance,
        //   however invariant in c: require(amount <= balances[msg.sender]) ensures withdraw only succeeds when amount <= recorded balance,
        //   and transfer(amount) sends exactly amount. Thus if it succeeded, this contract's balance increases by exactly amount and
        //   contract balance decreases by at least amount (transfer may fail only via revert). We assert these observable consequences.

        assert(
            withdrewReverted
                ? (afterContractBal == beforeContractBal && afterThisBal == beforeThisBal)
                : (afterThisBal == beforeThisBal + amount && beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal >= amount)
        );
    }

    receive() external payable {}
}

